-- --- 6. the deva tarpanam -------------------------------------------------------
insert into public.pooja_steps
  (pooja_id, step_number, step_title_en, step_title_ta, instruction_en, instruction_ta,
   meaning_en, philosophy_en, phase, modes, gender_rule, source_ref, scripts_generated)
values
  ('nitya_panchayatana', 36, 'Deva Tarpanam', 'தேவ தர்ப்பணம்',
   'After each tarpayaami, pour an uddharani of water from the right palm into a cup. Eight names, then the same eight as consorts, then one that sweeps up everyone invoked.',
   'ஒவ்வொரு தர்ப்பயாமிக்குப் பின்னும், வலது உள்ளங்கையிலிருந்து ஒரு உத்தரிணி நீரை கிண்ணத்தில் விடவும். எட்டு நாமங்கள், பின் அவர்களின் பத்தினியர் எட்டு, பின் ஆவாஹனம் செய்யப்பட்ட அனைவருக்கும் ஒன்று.',
   'Bhava, Sharva, Ishana, Pashupati, Rudra, Ugra, Bhima and Mahat; then the consorts of the same eight; and finally all the deities invoked.',
   'Seventeen offerings, not sixteen. The closing catch-all -- aavaahita sarva dEvataah tarpayaami -- is the part a hand-built list would most easily drop, and it is the one that makes sure nobody invoked goes without.',
   'uttara', array['main']::text[], 'all', 'Sampradaya Vratha Pooja Vidhi (Giri), pp.27-51, pp.47-48', true)
on conflict (pooja_id, step_title_en) do nothing;
