-- --- assert ------------------------------------------------------------------
do $$
declare n int;
begin
  select count(*) into n from public.pooja_steps where pooja_id = 'nitya_panchayatana';
  if n <> 39 then raise exception 'nitya has % steps, expected 39', n; end if;

  select count(distinct step_number) into n from public.pooja_steps
   where pooja_id = 'nitya_panchayatana';
  if n <> 39 then raise exception 'step numbers are not distinct'; end if;

  select count(*) into n from public.pooja_steps
   where pooja_id = 'nitya_panchayatana' and (step_number < 1 or step_number > 39);
  if n > 0 then raise exception '% steps outside 1..39', n; end if;

  -- Five avahanams and five archanas, which is what makes this pooja different.
  select count(*) into n from public.pooja_steps
   where pooja_id = 'nitya_panchayatana' and step_title_en like 'Avahanam%';
  if n <> 5 then raise exception '% avahanam steps, expected 5', n; end if;
  select count(*) into n from public.pooja_steps
   where pooja_id = 'nitya_panchayatana' and step_title_en like 'Archana%';
  if n <> 5 then raise exception '% archana steps, expected 5', n; end if;

  select count(*) into n from public.archana_items a
    join public.pooja_steps s on s.id = a.pooja_step_id
   where s.pooja_id = 'nitya_panchayatana' and s.step_title_en = 'Archana — Vinayaka';
  if n <> 16 then raise exception 'Archana — Vinayaka has % rows, expected 16', n; end if;
  select count(*) into n from public.archana_items a
    join public.pooja_steps s on s.id = a.pooja_step_id
   where s.pooja_id = 'nitya_panchayatana' and s.step_title_en = 'Archana — Surya';
  if n <> 12 then raise exception 'Archana — Surya has % rows, expected 12', n; end if;
  select count(*) into n from public.archana_items a
    join public.pooja_steps s on s.id = a.pooja_step_id
   where s.pooja_id = 'nitya_panchayatana' and s.step_title_en = 'Archana — Vishnu';
  if n <> 24 then raise exception 'Archana — Vishnu has % rows, expected 24', n; end if;
  select count(*) into n from public.archana_items a
    join public.pooja_steps s on s.id = a.pooja_step_id
   where s.pooja_id = 'nitya_panchayatana' and s.step_title_en = 'Archana — Shiva';
  if n <> 8 then raise exception 'Archana — Shiva has % rows, expected 8', n; end if;
  select count(*) into n from public.archana_items a
    join public.pooja_steps s on s.id = a.pooja_step_id
   where s.pooja_id = 'nitya_panchayatana' and s.step_title_en = 'Archana — Devi';
  if n <> 8 then raise exception 'Archana — Devi has % rows, expected 8', n; end if;
  select count(*) into n from public.archana_items a
    join public.pooja_steps s on s.id = a.pooja_step_id
   where s.pooja_id = 'nitya_panchayatana' and s.step_title_en = 'Deva Tarpanam';
  if n <> 17 then raise exception 'tarpanam has % rows, expected 17', n; end if;

  -- Every step has both instruction languages and all three scripts where it
  -- has any Devanagari at all.
  select count(*) into n from public.pooja_steps
   where pooja_id = 'nitya_panchayatana'
     and (coalesce(trim(instruction_en), '') = '' or coalesce(trim(instruction_ta), '') = '');
  if n > 0 then raise exception '% nitya steps are missing an instruction', n; end if;
  select count(*) into n from public.pooja_steps
   where pooja_id = 'nitya_panchayatana'
     and coalesce(trim(mantra_sanskrit), '') <> ''
     and (mantra_tamil is null or mantra_translit is null);
  if n > 0 then raise exception '% nitya steps are missing a script', n; end if;

  -- No ASCII colon, no mantra-shaped title.
  select count(*) into n from public.pooja_steps
   where pooja_id = 'nitya_panchayatana'
     and (mantra_sanskrit like '%:%' or mantra_tamil like '%:%' or mantra_translit like '%:%');
  if n > 0 then raise exception '% nitya steps carry an ASCII colon', n; end if;
  select count(*) into n from public.pooja_steps
   where pooja_id = 'nitya_panchayatana'
     and (length(coalesce(step_title_en, '')) > 60 or length(coalesce(step_title_ta, '')) > 60);
  if n > 0 then raise exception '% nitya titles look like mantra text', n; end if;

  -- The purvangam really was copied, not left empty.
  select count(*) into n from public.pooja_steps
   where pooja_id = 'nitya_panchayatana' and phase = 'purvangam'
     and coalesce(trim(mantra_sanskrit), '') = '';
  if n > 0 then raise exception '% copied purvangam steps came across empty', n; end if;
end $$;


-- Carriage returns, from pasting this file into a browser SQL editor. See
-- scripts/_migration.mjs.
do $$
declare
  r record;
  n bigint;
begin
  for r in
    select c.table_name, c.column_name
      from information_schema.columns c
      join information_schema.tables t
        on t.table_schema = c.table_schema and t.table_name = c.table_name
     where c.table_schema = 'public'
       and t.table_type = 'BASE TABLE'
       and c.data_type in ('text', 'character varying', 'character')
  loop
    execute format(
      'update public.%I set %I = replace(%I, chr(13), %L)'
      || ' where position(chr(13) in %I) > 0',
      r.table_name, r.column_name, r.column_name, '', r.column_name
    );
    get diagnostics n = row_count;
    if n > 0 then
      raise notice 'stripped CR from % row(s) of %.%', n, r.table_name, r.column_name;
    end if;
  end loop;
end $$;

